from datetime import date, timedelta
from typing import List, Optional

def _parse_date(d: str) -> Optional[date]:
    """Parse a YYYY-MM-DD string, accepting non‑zero‑padded month/day."""
    if not isinstance(d, str):
        return None
    parts = d.strip().split('-')
    if len(parts) != 3:
        return None
    try:
        y, m, day = int(parts[0]), int(parts[1]), int(parts[2])
        return date(y, m, day)
    except Exception:
        return None

def business_days(start: str, end: str, holidays: List[str]) -> int:
    """
    Count business days from start (inclusive) to end (exclusive).
    A business day is Monday to Friday and not in the holidays list.
    If end is not after start, return 0.
    """
    start_dt = _parse_date(start)
    end_dt = _parse_date(end)
    if not start_dt or not end_dt or end_dt <= start_dt:
        return 0

    holiday_set = set()
    for h in holidays:
        hd = _parse_date(h)
        if hd:
            holiday_set.add(hd)

    count = 0
    current = start_dt
    while current < end_dt:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += timedelta(days=1)

    return count
